steps.script:
for uid in ["U_BOYZ_B", "U_WARBOSS_A"]:
	GameState.get_unit(uid)["flags"].merge({"charged_this_turn": true, "fights_first": true}, true)
for m in GameState.get_unit("U_CUSTODIAN_GUARD_A").models:
	m["wounds"] = 99
	m["current_wounds"] = 99
return true

var b = GameState.state.duplicate(true)
var a = {"attacker": "U_BOYZ_B", "target": "U_CUSTODIAN_GUARD_A", "weapon": "Choppa"}
var on = RulesEngine._resolve_melee_assignment_hits(a, "U_BOYZ_B", b, RulesEngine.RNGService.new(5))
var swingers = int(on.hit_context.model_count)
b.units.U_BOYZ_B.flags.erase("ork11e_plus_attacks_melee")
var off = RulesEngine._resolve_melee_assignment_hits(a, "U_BOYZ_B", b, RulesEngine.RNGService.new(5))
print("UC scenario: Choppa attacks with=%d without=%d swinging models=%d" % [int(on.hit_context.total_attacks), int(off.hit_context.total_attacks), swingers])
return swingers > 0 and int(on.hit_context.total_attacks) - int(off.hit_context.total_attacks) == swingers
